{"implementation":"def solve(case):
    segments = case["segments"]
    budget = case["budget"]
    allocations = [segment["minimum"] for segment in segments]
    total = sum(allocations)

    if budget > total:
        remaining = budget - total
        for index in sorted(range(len(segments)), key=lambda i: (-segments[i]["importance"], i)):
            available = segments[index]["capacity"] - allocations[index]
            if available > 0:
                amount = min(remaining, available)
                allocations[index] += amount
                remaining -= amount
                total += amount
                if remaining == 0:
                    break

    by_name = {segment["name"]: allocations[index] for index, segment in enumerate(segments)}
    return {"allocations": allocations, "by_name": by_name, "total": total}"}
